//! 🧪️ Canonical output, unchanged original fields and every physical receipt survive native export and cancellation.
use super::*;
use semio_framework_dsl_record::{BorrowedDslRecord,native_encoding::FieldProjectionSource};
use store::os_store::serialization::{OriginalSnapshotPackExport as Export,OriginalSnapshotPackView as View};
#[derive(semio_framework_dsl_record_derive::DslRecord)]
#[dsl(layout="lines")]
struct Record{title:String,enabled:bool}
fn view(record:&Record)->View<'_>{View{source:record,spec:<Record as BorrowedDslRecord>::RECORD,envelope:"test.original-export"}}
fn funded(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(4096),maximum_capacity_bytes:d.capacity_bytes.max(4096),maximum_release_bytes:d.release_bytes.max(4096),maximum_depth:d.depth.max(256),maximum_items:1}}
fn denied(d:RetirementDemand)->Vec<RetainedCloneGrant>{(0..5).filter_map(|axis|{let mut g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>g.maximum_release_bytes-=1,4 if d.depth>0=>g.maximum_depth-=1,_=>return None}Some(g)}).collect()}
#[test]
fn original_snapshot_pack_export_preserves_source_and_canonical_bytes_through_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let expected=Record{title:law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize),enabled:true};let body=store::pack_rt::encode_document(&Record::__dsl_spec(),&expected.__dsl_to_record(),&Default::default()).unwrap();let envelope=store::semio_format::SemioEnvelope::from_envelope_id(law["envelope"].as_str().unwrap(),store::semio_format::Component::Pack,1).unwrap();let reference=store::semio_format::wrap_binary(&envelope,&body);
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut record=None;let bytes=expected.title.len();let d=RetirementDemand{copy_bytes:bytes+size_of::<Record>(),capacity_bytes:bytes,depth:1,..Default::default()};turn(&mut caller,&mut decoder,funded(d),|cx|{admit_original_construction(cx,&mut record,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:1},|_|Ok((Record{title:expected.title.clone(),enabled:true},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(())});let record=record.unwrap();let pointer=record.title.as_ptr();let identity=record.projection_identity();let mut owner=None;let birth=Export::capture_demands();for g in denied(birth){turn(&mut caller,&mut decoder,g,|cx|{assert!(!Export::admit(view(&record),17,cx,&mut owner)?);Ok(())});assert!(owner.is_none());}turn(&mut caller,&mut decoder,funded(birth),|cx|{assert!(Export::admit(view(&record),17,cx,&mut owner)?);Ok(())});let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,funded(birth),|cx|{assert!(owner.as_mut().unwrap().advance(view(&record),17,cx).is_err());Ok(())});turn(&mut caller,&mut decoder,funded(birth),|cx|{assert!(owner.as_mut().unwrap().advance(view(&record),18,cx).is_err());Ok(())});
 for index in 0..4000000{if cut==Some(index)||owner.as_ref().unwrap().ready(){break}let d=owner.as_ref().unwrap().advance_demands().unwrap();for g in denied(d){turn(&mut caller,&mut decoder,g,|cx|{assert!(!owner.as_mut().unwrap().advance(view(&record),17,cx)?);Ok(())});assert_eq!(owner.as_ref().unwrap().advance_demands().unwrap(),d);}turn(&mut caller,&mut decoder,funded(d),|cx|owner.as_mut().unwrap().advance(view(&record),17,cx));assert!(index<3999999,"native snapshot export must complete");}assert_eq!((record.title.as_ptr(),record.projection_identity()),(pointer,identity));if cut.is_none(){assert!(owner.as_ref().unwrap().ready());let mut output=None;for g in denied(Export::take_demands()){turn(&mut caller,&mut decoder,g,|cx|{assert!(!owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert!(output.is_none()&&owner.as_ref().unwrap().ready());}turn(&mut caller,&mut decoder,funded(birth),|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});let output=output.unwrap();assert_eq!(output.to_vec_owner(),reference);if let Some(path)=std::env::var_os("ENERGY_EXPORT_ORACLE"){std::fs::write(path,output.to_vec_owner()).unwrap();}close_typed(output,&mut caller,&mut decoder);}else{caller.cancel().cancel_now();for index in 0..4000000{if owner.as_ref().unwrap().terminal_is_empty(){break}let d=owner.as_ref().unwrap().close_demands().unwrap();for g in denied(d){turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{assert!(!owner.as_mut().unwrap().close(cx)?);Ok(())}));assert_eq!(owner.as_ref().unwrap().close_demands().unwrap(),d);}turn(&mut caller,&mut decoder,funded(d),|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close(cx)));assert!(index<3999999);}}
 let d=Export::boxed_release_demands();turn(&mut caller,&mut decoder,funded(d),|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{owner=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let d=RetirementDemand{copy_bytes:size_of::<Record>(),release_bytes:record.title.capacity(),depth:1,..Default::default()};turn(&mut caller,&mut decoder,funded(d),|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{drop(record);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));while !decoder.terminal_is_empty(){caller.turn(funded(Default::default()),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(funded(Default::default()));}
}
